// Une variable propre à chaque thread.
static final ThreadLocal<String> UTILISATEUR = new ThreadLocal<>();

void traiterRequete(String nom) {
    UTILISATEUR.set(nom);   // on range une valeur dans le casier de CE thread
    try {
        afficherBienvenue(); // une méthode profonde peut la relire
    } finally {
        UTILISATEUR.remove(); // IMPORTANT : vider le casier, sinon fuite mémoire
    }
}

void afficherBienvenue() {
    // Pas besoin de passer le nom en paramètre : on le relit depuis le casier.
    System.out.println("Bonjour " + UTILISATEUR.get());
}

import java.lang.ScopedValue;

public class Contexte {
    // On declare la CLE une seule fois, partagee par toute l'application.
    // Le <String> dit : cette cle portera une valeur de type String.
    public static final ScopedValue<String> UTILISATEUR = ScopedValue.newInstance();

    // A ce stade, aucune valeur n'est liee.
    // UTILISATEUR.get() ici leverait une exception car rien n'est lie.
    // isBound() permet de verifier s'il y a une valeur disponible.
    static boolean yAtIlUnUtilisateur() {
        return UTILISATEUR.isBound();
    }
}

import java.lang.ScopedValue;

public class Demo {
    static final ScopedValue<String> UTILISATEUR = ScopedValue.newInstance();

    public static void main(String[] args) {
        // On lie la valeur "Ana" pour toute la duree du bloc run(...).
        ScopedValue.where(UTILISATEUR, "Ana").run(() -> {
            saluer(); // une methode profonde relit la valeur
        });
        // Ici, hors du bloc, la valeur n'est plus liee.
    }

    static void saluer() {
        // Pas de parametre passe : on lit directement depuis le Scoped Value.
        System.out.println("Bonjour " + UTILISATEUR.get()); // Bonjour Ana
    }
}

