import java.lang.ScopedValue;

static final ScopedValue<String> REQUETE_ID = ScopedValue.newInstance();

void traiterRequete(String id) {
    // On lie l'identifiant pour toute la duree du traitement.
    ScopedValue.where(REQUETE_ID, id).run(() -> {
        etape1();
        etape2();
    });
}

void etape1() {
    // N'importe quelle methode du bloc lit la meme valeur, en lecture seule.
    journaliser("debut etape 1");
}

void journaliser(String message) {
    // La valeur est immuable et garantie identique pendant tout l'appel.
    System.out.println("[" + REQUETE_ID.get() + "] " + message);
}

